INSERT INTO public."modules_content" ("id", "module_id", "stage_name", "stage_order", "stage_description", "module_context", "curriculum_reference", "is_active")
VALUES ('3f1fff41-f396-5513-813a-c55be840cf4e'::uuid, '73778e22-777d-5fb6-8ef3-00746e69f978'::uuid, 'engage'::public.lte_6e_stage, 1, 'Enter the workplace mission, learner role, pressure, authority boundary and required module outcome. Northstar Retail has a GenAI-generated response ready for an internal demonstration, but the response has not been cleared, the approved source is not attached and review completion is not recorded. The learner must record one exact visible concern, identify the evidence checked and state what remains uncertain without diagnosing, correcting or approving the response.', 'Northstar Retail has a GenAI-generated response ready for an internal demonstration, but the response has not been cleared, the approved source is not attached and review completion is not recorded. The learner must record one exact visible concern, identify the evidence checked and state what remains uncertain without diagnosing, correcting or approving the response.', '{"course_problem": "Northstar Retail is preparing a GenAI customer-support assistant that answers customer questions using approved business information. A generated response appears polished and confident, but the supplied records may show conflict with an approved source, internal-use information appearing in customer-facing output, incomplete review evidence, unclear source or review status, and deadline pressure encouraging premature use. The learner must inspect supplied records, identify workflow objects, classify evidence, recognise visible quality, evidence and boundary signals, record uncertainty, organise a safe review handoff and prepare a permitted first review action without diagnosing the technical cause, changing the response, approving the output or closing the case.", "module_problem": "Northstar Retail has a GenAI-generated response ready for an internal demonstration, but the response has not been cleared, the approved source is not attached and review completion is not recorded. The learner must record one exact visible concern, identify the evidence checked and state what remains uncertain without diagnosing, correcting or approving the response.", "artifact": "GenAI Workflow Entry Record", "artifact_statement": "Create an evidence-linked observation showing what was noticed, which supplied record was checked, what remains uncertain and that the record is being submitted to the GenAI Workflow Owner rather than treated as a decision."}'::jsonb, TRUE)
ON CONFLICT DO NOTHING;
