INSERT INTO public."modules_content" ("id", "module_id", "stage_name", "stage_order", "stage_description", "module_context", "curriculum_reference", "is_active")
VALUES ('4e519e16-b4a0-5d75-abcc-512a635bdc86'::uuid, 'a5aefe99-2026-5a8b-976e-5b2d6387645f'::uuid, 'engage'::public.lte_6e_stage, 1, 'Enter the workplace mission, assigned support role, pressure, authority boundary and required module outcome. The learner is moving from inspection to supported execution, but the sandbox includes editable fields, locked controls and actions that require owner approval. The learner must distinguish permitted supported tasks from prohibited production or governance actions before making any change.', 'The learner is moving from inspection to supported execution, but the sandbox includes editable fields, locked controls and actions that require owner approval. The learner must distinguish permitted supported tasks from prohibited production or governance actions before making any change.', '{"course_problem": "Northstar Retail needs a controlled GenAI customer-support workflow prepared for sandbox testing. The GenAI Workflow Owner supplies an approved workflow request, a structured prompt template, approved and restricted source records, a controlled sandbox, defined test cases and permitted revision rules. The learner must complete assigned workflow fields, assemble approved prompt components, connect permitted source context, run supplied tests, record evidence, make only explicitly permitted routine revisions and submit a versioned evidence pack. The learner may not independently design the complete workflow, use unapproved sources, change protected controls, approve customer-facing output, deploy to production or close significant exceptions.", "module_problem": "The learner is moving from inspection to supported execution, but the sandbox includes editable fields, locked controls and actions that require owner approval. The learner must distinguish permitted supported tasks from prohibited production or governance actions before making any change.", "artifact": "L2 Readiness and Authority Record", "artifact_statement": "Create a readiness record that identifies the assigned role, allowed tools, editable fields, locked controls, escalation triggers and the learnerâ€™s confirmation that only authorised sandbox actions will be performed."}'::jsonb, TRUE)
ON CONFLICT DO NOTHING;
